class DiagnosisProbe:
    def run_full_diagnosis(self, train_loader):
        saved_state = capture_module_modes_and_rng_states(self.view.model)
        try:
            seed_probe_rng(42)
            self.view.model.eval()
            with torch.no_grad():
                prefixes = fixed_training_prefix_sample(self.view.user_train)
                frequency_bins = bins_from_training_histories(self.view.user_train)
                observations = []
                for user, sequence, target in prefixes:
                    eligible = original_prefix_eligibility(sequence, target)
                    bands = matched_recent_and_older_positions(sequence, keep_terminal=True)
                    clean = exact_chunked_measure(self.view, sequence, target, eligible)
                    for band in bands:
                        altered, coverage = replace_in_place(sequence, band, frequency_bins,
                                                             exclude_target=target)
                        if coverage.is_valid:
                            changed = exact_chunked_measure(self.view, altered, target, eligible)
                            observations.append(paired_record(user, band, clean, changed, coverage))
                metrics = aggregate_with_user_cluster_bootstrap(observations)
                return {'metrics': metrics,
                        'metric_definitions': definitions_with_counts_and_limitations()}
        finally:
            restore_module_modes_and_rng_states(saved_state)

def diagnosis_interpreter_prompt(raw_diagnosis):
    return grounded_prompt(raw_diagnosis,
        distinguish_training_sensitivity_from_generalization=True,
        require_measured_evidence=True,
        preserve_nextitnet_and_single_model_constraint=True)
